CREATE OR REPLACE FUNCTION public.lab_coordinate_near(lat numeric,lng numeric,city_lat numeric,city_lng numeric) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT coalesce(abs(lat)<=90 AND abs(lng)<=180 AND 6371*2*asin(sqrt(least(1::double precision,power(sin(radians((city_lat-lat)::double precision)/2),2)+cos(radians(lat::double precision))*cos(radians(city_lat::double precision))*power(sin(radians((city_lng-lng)::double precision)/2),2))))<=30,false); $$;
CREATE OR REPLACE FUNCTION public.lab_patient_city_key(c text,s text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN public.dre_feegow_normalizar_nome(c) IN ('santa helena','santa helena de goias') THEN 'santa helena de goias' ELSE public.dre_feegow_normalizar_nome(c) END||'|'||CASE WHEN public.dre_feegow_normalizar_nome(s)='goias' THEN 'GO' ELSE upper(btrim(s)) END; $$;
CREATE OR REPLACE FUNCTION public.lab_clear_changed_patient_coordinate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF ROW(NEW.cep,NEW.bairro,NEW.cidade,NEW.estado) IS DISTINCT FROM ROW(OLD.cep,OLD.bairro,OLD.cidade,OLD.estado) THEN NEW.latitude:=null;NEW.longitude:=null; END IF;RETURN NEW; END; $$;
CREATE TRIGGER lab_clear_patient_old_coordinate BEFORE UPDATE OF cep,bairro,cidade,estado ON public.pacientes FOR EACH ROW EXECUTE FUNCTION public.lab_clear_changed_patient_coordinate();
CREATE OR REPLACE FUNCTION public.lab_apply_cached_patient_geo() RETURNS integer LANGUAGE plpgsql SET search_path=public AS $$ DECLARE n integer; BEGIN
WITH neighborhoods AS MATERIALIZED (SELECT public.dre_feegow_normalizar_nome(bairro) bairro_key,public.lab_patient_city_key(cidade,estado) city_key,avg(latitude) latitude,avg(longitude) longitude FROM public.geo_bairros WHERE latitude IS NOT NULL AND longitude IS NOT NULL GROUP BY 1,2), candidates AS MATERIALIZED (SELECT p.paciente_id,CASE WHEN public.lab_coordinate_near(cp.latitude,cp.longitude,c.latitude,c.longitude) AND public.lab_patient_city_key(cp.cidade,cp.estado)=c.chave THEN cp.latitude WHEN public.lab_coordinate_near(p.latitude,p.longitude,c.latitude,c.longitude) THEN p.latitude WHEN public.lab_coordinate_near(b.latitude,b.longitude,c.latitude,c.longitude) THEN b.latitude END latitude,CASE WHEN public.lab_coordinate_near(cp.latitude,cp.longitude,c.latitude,c.longitude) AND public.lab_patient_city_key(cp.cidade,cp.estado)=c.chave THEN cp.longitude WHEN public.lab_coordinate_near(p.latitude,p.longitude,c.latitude,c.longitude) THEN p.longitude WHEN public.lab_coordinate_near(b.latitude,b.longitude,c.latitude,c.longitude) THEN b.longitude END longitude FROM public.lab_paciente_geo_fila q JOIN public.pacientes p ON p.paciente_id=q.paciente_id JOIN public.lab_geo_cidades c ON c.chave=public.lab_patient_city_key(p.cidade,p.estado) LEFT JOIN public.ceps_geocodificados cp ON cp.cep=p.cep LEFT JOIN neighborhoods b ON b.bairro_key=public.dre_feegow_normalizar_nome(p.bairro) AND b.city_key=c.chave WHERE q.status='pendente' AND c.latitude IS NOT NULL AND c.longitude IS NOT NULL), updated AS (UPDATE public.pacientes p SET latitude=a.latitude,longitude=a.longitude FROM candidates a WHERE p.paciente_id=a.paciente_id RETURNING p.paciente_id,p.latitude,p.longitude) UPDATE public.lab_paciente_geo_fila q SET status=CASE WHEN u.latitude IS NOT NULL AND u.longitude IS NOT NULL THEN 'concluido' ELSE 'pendente' END,erro=null,atualizado_em=now() FROM updated u WHERE q.paciente_id=u.paciente_id;
GET DIAGNOSTICS n=ROW_COUNT;RETURN n;END; $$;
REVOKE ALL ON FUNCTION public.lab_apply_cached_patient_geo() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.lab_apply_cached_patient_geo() TO service_role;